// MCP tools backed by the same cores as the batch-45 browser tools (src/tools_core45.js, generated by gen_tools_core.py).
// Pure functions — no D1/R2 access. Each returns an MCP tool result.
import { MGDDataMatrix, MGDSwatch, MGDGraph, MGDTranscript, MGDResize45, MGDCase45 } from "./tools_core45.js";
import { bwipDM } from "./bwip_dm.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text) => ({ content: [{ type: "text", text }] });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const int = (x, d, lo, hi) => { const n = parseInt(x, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const numIn = (x, d, lo, hi) => { const n = Number(x); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const svgBlock = (svg) => "```svg\n" + svg + "\n```";
const fence = (lang, s) => "```" + lang + "\n" + s.replace(/\n$/, "") + "\n```";
const hexColor = (x, d) => (/^#?[0-9a-f]{3}([0-9a-f]{3})?$/i.test(str(x, 9).trim()) ? "#" + str(x, 9).trim().replace("#", "") : d);
const b64 = (u8) => { let s = ""; for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000)); return btoa(s); };

const SWATCH_LAYOUTS = ["cards", "grid", "strips", "circles", "bar", "table"];
const SWATCH_FORMATS = ["css", "scss", "tailwind", "json", "csv", "txt", "gpl", "sketch", "procreate", "ase", "aco"];
const GRAPH_TYPES = ["line", "bar", "hbar", "stacked", "stackedh", "area", "stackedarea", "scatter", "combo", "histogram"];
const SUB_FORMATS = ["srt", "vtt", "txt", "txtts", "csv"];
const PRESET_IDS = MGDResize45.PRESETS.map((p) => p[0]);

