const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools45Tool(name) { return NAMES.has(name); }

export function callTools45Tool(name, a) {
  a = a || {};
  try {
    if (name === "generate_data_matrix") return dataMatrix(a);
    if (name === "make_color_swatches") return swatches(a);
    if (name === "make_graph") return graph(a);
    if (name === "convert_subtitles") return subtitles(a);
    if (name === "image_size_calculator") return imageSize(a);
    if (name === "convert_text_case") return textCase(a);
  } catch (e) {
    return err("The tool failed: " + (e && e.message ? e.message : String(e)));
  }
  return err("Unknown tool: " + name);
}

function dataMatrix(a) {
  const data = str(a.data, 2000);
  if (!data.trim()) return err("Pass data to encode.");
  const mode = a.mode === "gs1" || (a.mode !== "text" && /^\(\d{2,4}\)/.test(data.trim())) ? "gs1" : "text";
  const size = /^\d{1,3}x\d{1,3}$/.test(str(a.size, 8)) ? a.size : "auto";
  const shape = ["rect", "dmre"].includes(a.shape) ? a.shape : "square";
  const cfg = { mode, text: data, size, shape, escapes: true };
  let g = null;
  if (mode === "gs1") { g = MGDDataMatrix.parseGS1(data); if (g.errors.length) return err("GS1 data is not valid:\n- " + g.errors.join("\n- ")); }
  let m;
  try { m = MGDDataMatrix.encode(bwipDM, cfg); } catch (e) { return err("Could not encode: " + MGDDataMatrix.cleanError(e && e.message || e)); }
  const fg = hexColor(a.color, "#000000"), bg = hexColor(a.background, "#ffffff");
  const svg = MGDDataMatrix.toSVG(m, { quiet: int(a.quiet_zone, 2, 0, 10), module: int(a.module_px, 8, 1, 40), unit: "px", fg, bg });
  const sym = `${m.h}x${m.w}`, cap = MGDDataMatrix.capacity(sym);
  const capText = cap ? ` Capacity of this size: ${cap[0]} digits / ${cap[1]} alphanumeric / ${cap[2]} bytes.` : "";
  const els = g ? "\n\n| AI | Meaning | Value |\n|---|---|---|\n" + g.elements.map((e) => `| (${e.ai}) | ${e.title} | ${e.value} |`).join("\n") + `\n\nHuman-readable text: ${g.hri}` : "";
  return ok(`${mode === "gs1" ? "GS1 " : ""}Data Matrix, ${sym} modules (${m.h} rows × ${m.w} columns).${capText}${els}\n\n${svgBlock(svg)}\n\nPNG at a set DPI, PDF/EPS vectors, batch CSV → ZIP and label sheets: ${T}/data-matrix-generator/`);
}

function swatches(a) {
  const src = Array.isArray(a.colors) ? a.colors.slice(0, 200).map((c) => str(c, 100)).join("\n") : str(a.colors, 20000);
  let colors = MGDSwatch.parse(src).slice(0, 60);
  if (!colors.length) return err("No colours found. Pass HEX (#2a9d8f), rgb(), hsl() or CSS colour names.");
  const mode = ["tints", "shades", "tones", "both"].includes(a.scale) ? a.scale : "";
  if (mode) {
    const steps = int(a.steps, 5, 2, 12);
    colors = colors.flatMap((c) => MGDSwatch.scale(c.hex, mode, steps).map((hex) => ({ hex }))).slice(0, 120);
  }
  const layout = SWATCH_LAYOUTS.includes(a.layout) ? a.layout : "cards";
  const r = MGDSwatch.svg(colors, { layout, title: str(a.title, 120), labels: { name: 1, hex: 1, rgb: 1, cmyk: layout === "table" ? 1 : 0 } });
  const rows = colors.map((c) => { const I = MGDSwatch.info(c.hex); return `| ${c.name || I.name} | ${I.hex.toUpperCase()} | ${I.rgb.join(", ")} | ${I.cmyk.join(", ")} | ${I.hsl[0]}°, ${I.hsl[1]}%, ${I.hsl[2]}% | ${I.text === "#ffffff" ? "white" : "dark"} (${I.text === "#ffffff" ? I.contrastWhite : I.contrastBlack}:1) |`; }).join("\n");
  const name = str(a.palette_name, 60) || "Swatches";
  const fmts = (Array.isArray(a.formats) && a.formats.length ? a.formats : ["css"]).filter((f) => SWATCH_FORMATS.includes(f)).slice(0, 11);
  const ex = fmts.map((f) => {
    if (f === "ase") return `Adobe Swatch Exchange (${name}.ase), base64:\n${fence("text", b64(MGDSwatch.ase(colors, name)))}`;
    if (f === "aco") return `Photoshop swatches (${name}.aco), base64:\n${fence("text", b64(MGDSwatch.aco(colors)))}`;
    if (f === "procreate") return `Procreate: save as Swatches.json and zip it, renamed to ${name}.swatches:\n${fence("json", MGDSwatch.procreate(colors, name))}`;
    if (f === "gpl") return `GIMP / Inkscape / Krita palette (${name}.gpl):\n${fence("text", MGDSwatch.gpl(colors, name))}`;
    if (f === "sketch") return `Sketch Palettes (.sketchpalette):\n${fence("json", MGDSwatch.sketch(colors))}`;
    const lang = { css: "css", scss: "scss", tailwind: "js", json: "json", csv: "csv", txt: "text" }[f];
    return `${f.toUpperCase()}:\n${fence(lang, MGDSwatch[f](colors))}`;
  }).join("\n\n");
  return ok(`${colors.length} colour${colors.length === 1 ? "" : "s"}${mode ? ` (${mode} scale)` : ""}.\n\n| Name | HEX | RGB | CMYK | HSL | Best text |\n|---|---|---|---|---|---|\n${rows}\n\n${svgBlock(r.svg)}\n\n${ex}\n\nPrintable Letter/A4 sheets, PNG/PDF and colours picked from photos: ${T}/color-swatch-generator/`);
}

function graph(a) {
  const text = str(a.data, 200000).split(/\r?\n/).slice(0, 2001).join("\n");
  const d = MGDGraph.parse(text);
  if (!d || !d.series || !d.series.length || !d.labels.length) return err("Couldn't read the data. Pass CSV with a header row, e.g. 'Month,Sales\\nJan,120\\nFeb,150'.");
  const type = GRAPH_TYPES.includes(a.type) ? a.type : "line";
  const o = { type, w: int(a.width, 960, 320, 2400), h: int(a.height, 600, 240, 1800), title: str(a.title, 140), subtitle: str(a.subtitle, 200), xLabel: str(a.x_label, 80), yLabel: str(a.y_label, 80),
    palette: MGDGraph.PALS[a.palette] ? a.palette : "vivid", values: !!a.values, trend: !!a.trend, log: !!a.log, smooth: !!a.smooth, prefix: str(a.prefix, 6), suffix: str(a.suffix, 10), xNumeric: true };
  if (["top", "bottom", "right", "none"].includes(a.legend)) o.legend = a.legend;
  if (a.bins) o.bins = int(a.bins, 10, 2, 100);
  const r = MGDGraph.svg(d, o);
  const st = r.stats || {};
  const notes = [];
  Object.keys(st).filter((k) => k !== "histogram" && st[k] && st[k].slope != null).forEach((k) => { const t = st[k];
    notes.push(`Trendline (${k}): y = ${+(+t.slope).toPrecision(4)}x ${t.intercept < 0 ? "−" : "+"} ${Math.abs(+(+t.intercept).toPrecision(4))}, R² = ${(+t.r2).toFixed(3)} (n = ${t.n})`); });
  if (st.histogram) notes.push(`Histogram bins: ${st.histogram.labels.map((l, i) => `${l} (${st.histogram.counts[i]})`).join(", ")}`);
  const series = d.series.map((s) => s.name).join(", ");
  return ok(`${type} graph: ${d.labels.length} ${type === "scatter" ? "points" : "categories"}, ${d.series.length} series (${series}).${notes.length ? "\n" + notes.join("\n") : ""}\n\n${svgBlock(r.svg)}\n\nEdit live, import .xlsx, export PNG/SVG/PDF: ${T}/graph-maker/`);
}

function subtitles(a) {
  let segs = [];
  if (Array.isArray(a.segments) && a.segments.length) {
    segs = a.segments.slice(0, 20000).map((s) => { const st = Number(s && s.start) || 0; return { s: st, e: Number.isFinite(Number(s.end)) ? Number(s.end) : st + 3, t: str(s && s.text, 2000).replace(/\s+/g, " ").trim() }; }).filter((s) => s.t);
  } else {
    segs = MGDTranscript.parseSubs(str(a.text, 500000));
  }
  if (!segs.length) return err("No cues found. Pass SRT or WebVTT text (with '00:00:01,000 --> 00:00:03,000' timings) or a segments array.");
  const shift = numIn(a.shift_seconds, 0, -360000, 360000);
  if (shift) segs = segs.map((s) => ({ s: Math.max(0, s.s + shift), e: Math.max(0, s.e + shift), t: s.t })).filter((s) => s.e > 0);
  const to = SUB_FORMATS.includes(a.to) ? a.to : "srt";
  const out = MGDTranscript.build(segs, to, { maxChars: int(a.max_chars, 42, 16, 120), paraGap: numIn(a.paragraph_gap, 1.5, 0, 60) });
  const last = segs[segs.length - 1];
  const lang = to === "csv" ? "csv" : "text";
  return ok(`${segs.length} cues, ${MGDTranscript.words(segs)} words, ends at ${MGDTranscript.short(last.e)}${shift ? `, shifted ${shift > 0 ? "+" : ""}${shift}s` : ""} → ${to.toUpperCase()}.\n\n${fence(lang, out)}\n\nTranscribe audio or video to text/SRT free in your browser (no upload): ${T}/video-to-text/`);
}

const r2 = (x) => Math.round(x * 100) / 100;
const gcd = (x, y) => (y ? gcd(y, x % y) : x);
const ratio = (w, h) => { const g = gcd(w, h) || 1; const a = w / g, b = h / g; return a <= 50 && b <= 50 ? `${a}:${b}` : `${r2(w / h)}:1`; };

function imageSize(a) {
  if (a.preset === "list") {
    const groups = {};
    MGDResize45.PRESETS.forEach((p) => { (groups[p[4]] = groups[p[4]] || []).push(`${p[0]} — ${p[1]}: ${p[2]}×${p[3]}`); });
    return ok(Object.keys(groups).map((g) => `${g}\n` + groups[g].map((l) => "- " + l).join("\n")).join("\n\n"));
  }
  const preset = a.preset ? MGDResize45.PRESETS.find((p) => p[0] === str(a.preset, 40).toLowerCase()) : null;
  if (a.preset && !preset) return err(`Unknown preset '${str(a.preset, 40)}'. Pass preset 'list' to see them. Some ids: ${PRESET_IDS.slice(0, 12).join(", ")}…`);
  const mode = preset ? "preset" : ["px", "percent", "print", "preset"].includes(a.mode) ? a.mode : "px";
  const dpi = int(a.dpi, preset && MGDResize45.PRESET_DPI[preset[0]] || 300, 1, 2400);
  const unit = ["in", "cm", "mm"].includes(a.unit) ? a.unit : "in";
  const sw = int(a.source_width, 0, 0, 100000), sh = int(a.source_height, 0, 0, 100000);
  if (!sw || !sh) {
    if (mode === "print" && (a.width || a.height)) {
      const w = MGDResize45.toPx(a.width, unit, dpi), h = MGDResize45.toPx(a.height, unit, dpi);
      return ok(`${a.width || "?"} × ${a.height || "?"} ${unit} at ${dpi} DPI = ${w || "?"} × ${h || "?"} px${w && h ? ` (${r2(w * h / 1e6)} MP, ${ratio(w, h)})` : ""}.\n\nResize photos to an exact print size with the DPI tag set: ${T}/image-resizer/`);
    }
    if (preset) return ok(`${preset[1]}: ${preset[2]} × ${preset[3]} px (${ratio(preset[2], preset[3])}).${MGDResize45.PRESET_DPI[preset[0]] ? ` Prints at ${MGDResize45.PRESET_DPI[preset[0]]} DPI.` : ""}\n\nPass source_width and source_height to get the crop or padding for your image. Resize free in the browser: ${T}/image-resizer/`);
    return err("Pass source_width and source_height (or mode 'print' with width/height to convert a print size to pixels).");
  }
  const o = { mode, unit, dpi, pct: numIn(a.percent, 100, 0.1, 10000), lock: a.lock_aspect !== false, noEnlarge: !!a.no_enlarge, fit: ["contain", "cover", "pad", "stretch"].includes(a.fit) ? a.fit : preset ? "cover" : "contain" };
  if (preset) { o.w = preset[2]; o.h = preset[3]; } else { o.w = a.width; o.h = a.height; }
  const p = MGDResize45.plan(sw, sh, o);
  const ps = MGDResize45.printSize(p.w, p.h, dpi);
  const lines = [`Source ${sw} × ${sh} px (${ratio(sw, sh)}) → output ${p.w} × ${p.h} px (${ratio(p.w, p.h)}, ${r2(p.w * p.h / 1e6)} MP)${preset ? ` for ${preset[1]}` : ""}.`];
  if (p.fit === "cover" && (Math.round(p.sw) < sw || Math.round(p.sh) < sh)) lines.push(`Fit cover: crops the source to ${Math.round(p.sw)} × ${Math.round(p.sh)} px from (${Math.round(p.sx)}, ${Math.round(p.sy)}) — ${Math.round(100 - 100 * p.sw * p.sh / (sw * sh))}% of the image is cut off.`);
  if ((p.fit === "contain" || p.fit === "pad") && (p.dw < p.canvasW || p.dh < p.canvasH)) lines.push(`Fit ${p.fit}: the image is ${p.dw} × ${p.dh} px, padded with ${p.canvasW - p.dw} px horizontally and ${p.canvasH - p.dh} px vertically.`);
  if (p.fit === "stretch" && o.w && o.h && mode !== "percent" && Math.abs(p.w / p.h - sw / sh) > 0.01) lines.push("Fit stretch: the aspect ratio changes (the image is distorted).");
  if (p.enlarged) lines.push(`Upscaled ×${r2(Math.max(p.w / sw, p.h / sh))} — expect softness; pass no_enlarge to stop at the source size.`);
  lines.push(`Printed at ${dpi} DPI: ${r2(ps.in[0])} × ${r2(ps.in[1])} in = ${r2(ps.cm[0])} × ${r2(ps.cm[1])} cm.`);
  return ok(lines.join("\n") + `\n\nResize, crop or pad the actual files (batch + ZIP, no upload): ${T}/image-resizer/`);
}

function textCase(a) {
  const text = str(a.text, 200000);
  if (!text) return err("Pass text to convert.");
  const mode = MGDCase45.MODES.includes(a.case) ? a.case : "lower";
  const keep = Array.isArray(a.keep) ? a.keep.slice(0, 200).map((w) => str(w, 60)) : [];
  const r = MGDCase45.convert(text, mode, { keepAcronyms: !!a.keep_acronyms, keep, locale: str(a.locale, 10) || undefined });
  const notes = [];
  if (r.keptWords && r.keptWords.length) notes.push(`Kept as written: ${r.keptWords.slice(0, 30).join(", ")}`);
  if (r.capsLock) notes.push("The text looks like it was typed with Caps Lock on, so acronyms were not preserved.");
  return ok(`${mode} case${notes.length ? "\n" + notes.join("\n") : ""}:\n\n${fence("text", r.text)}\n\nAll 12 cases, file in/out: ${T}/case-converter/ · ${T}/lowercase-converter/`);
}
